import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const ROOT = join(__dirname, "..", "..", "..");
const SCRIPT = join(ROOT, "scripts", "build-brands.mjs");

const icon = (slug: string, extra: Record<string, unknown> = {}) => ({
  title: slug.toUpperCase(),
  slug,
  path: "M0 0h24v24H0z",
  source: `https://example.com/${slug}`,
  ...extra,
});
const NOTICES =
  "# Notices\n\n<!-- brands:start (generated by npm run build:brands, do not edit) -->\n<!-- brands:end -->\n\nAfter.\n";

let dir: string;
const file = (name: string) => join(dir, name);
const write = (name: string, value: unknown) =>
  writeFileSync(file(name), typeof value === "string" ? value : JSON.stringify(value));

/** Run the script on fixtures in the temporary folder. Returns the exit code and what it printed. */
function run(args: string[] = []) {
  try {
    const stdout = execFileSync(
      "node",
      [
        SCRIPT,
        "--icons",
        file("icons.json"),
        "--curated",
        file("curated.json"),
        "--allowlist",
        file("allowlist.json"),
        "--out",
        file("brandData.ts"),
        "--notices",
        file("NOTICES.md"),
        ...args,
      ],
      { encoding: "utf8", stdio: "pipe" },
    );
    return { code: 0, output: stdout };
  } catch (error) {
    const failed = error as { status: number; stderr: string };
    return { code: failed.status, output: failed.stderr };
  }
}

beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), "brands-"));
  write("icons.json", {
    version: "9.9.9",
    icons: [
      icon("alpha"),
      icon("beta", { license: { type: "CC0-1.0", url: "https://spdx.org/licenses/CC0-1.0" } }),
      icon("gamma", {
        license: { type: "CC-BY-SA-4.0", url: "https://spdx.org/licenses/CC-BY-SA-4.0" },
      }),
      icon("delta", { license: { type: "custom", url: "https://example.com/terms" } }),
    ],
  });
  write("allowlist.json", {});
  write("NOTICES.md", NOTICES);
});
afterEach(() => rmSync(dir, { recursive: true, force: true }));

describe("npm run build:brands, the licence gate", () => {
  it("writes the module and the notices for CC0 icons, an explicit CC0 included", () => {
    write("curated.json", ["beta", "alpha"]);
    expect(run().code).toBe(0);
    const module = readFileSync(file("brandData.ts"), "utf8");
    expect(module).toContain("from simple-icons 9.9.9");
    expect(module.indexOf('slug: "alpha"')).toBeLessThan(module.indexOf('slug: "beta"'));
    expect(module).toContain('license: "CC0-1.0"');
    expect(module).not.toContain("attribution");
    const notices = readFileSync(file("NOTICES.md"), "utf8");
    expect(notices).toContain("| ALPHA | CC0-1.0 |");
    expect(notices).toContain("Simple Icons");
    expect(notices).toContain("does not suggest endorsement");
    expect(notices.startsWith("# Notices")).toBe(true);
    expect(notices.endsWith("After.\n")).toBe(true);
  });

  it("fails for an icon with another licence that is not on the allowlist, and writes nothing", () => {
    write("curated.json", ["alpha", "gamma"]);
    const result = run();
    expect(result.code).toBe(1);
    expect(result.output).toMatch(
      /gamma: the licence is CC-BY-SA-4\.0, not CC0-1\.0, and "gamma" is not on scripts\/brands\/allowlist\.json/,
    );
    expect(() => readFileSync(file("brandData.ts"))).toThrow();
    expect(readFileSync(file("NOTICES.md"), "utf8")).toBe(NOTICES);
  });

  it("treats a custom licence like any other: it needs the allowlist", () => {
    write("curated.json", ["delta"]);
    expect(run().output).toMatch(/delta: the licence is custom/);
  });

  it("passes an allowed icon and writes its attribution to the module and to the notices", () => {
    write("curated.json", ["alpha", "gamma"]);
    write("allowlist.json", {
      gamma: {
        license: "CC-BY-SA-4.0",
        author: "A. Author",
        attribution: "Logo by A. Author, CC BY-SA 4.0.",
      },
    });
    expect(run().code).toBe(0);
    const module = readFileSync(file("brandData.ts"), "utf8");
    expect(module).toContain('license: "CC-BY-SA-4.0"');
    expect(module).toContain('author: "A. Author"');
    expect(module).toContain('attribution: "Logo by A. Author, CC BY-SA 4.0."');
    const notices = readFileSync(file("NOTICES.md"), "utf8");
    expect(notices).toContain("| GAMMA | CC-BY-SA-4.0 |");
    expect(notices).toContain(
      "- GAMMA: CC-BY-SA-4.0, by A. Author. Logo by A. Author, CC BY-SA 4.0.",
    );
  });

  it("fails when the allowlist records another licence than the icon has", () => {
    write("curated.json", ["gamma"]);
    write("allowlist.json", {
      gamma: { license: "CC-BY-4.0", author: "A", attribution: "x" },
    });
    expect(run().output).toMatch(
      /allowlist\.json says CC-BY-4\.0, simple-icons says CC-BY-SA-4\.0/,
    );
  });

  it("fails when an allowlist entry has no author or attribution", () => {
    write("curated.json", ["gamma"]);
    write("allowlist.json", { gamma: { license: "CC-BY-SA-4.0" } });
    const result = run();
    expect(result.output).toMatch(/"gamma" needs a non-empty "author"/);
    expect(result.output).toMatch(/"gamma" needs a non-empty "attribution"/);
  });

  it("fails on an allowlist entry for a brand the set does not ship, and on a slug the package lacks", () => {
    write("curated.json", ["alpha", "missing"]);
    write("allowlist.json", { beta: { license: "CC0-1.0", author: "A", attribution: "x" } });
    const result = run();
    expect(result.output).toMatch(/names "beta", which is not in curated\.json/);
    expect(result.output).toMatch(/names "missing", which simple-icons does not have/);
  });
});

describe("npm run build:brands, a re-run", () => {
  it("leaves no diff", () => {
    write("curated.json", ["alpha", "beta"]);
    run();
    const before = [
      readFileSync(file("brandData.ts"), "utf8"),
      readFileSync(file("NOTICES.md"), "utf8"),
    ];
    expect(run().output).toMatch(/wrote 0 file/);
    expect([
      readFileSync(file("brandData.ts"), "utf8"),
      readFileSync(file("NOTICES.md"), "utf8"),
    ]).toEqual(before);
  });

  it("--check passes when current and fails, naming the file, when the data changed", () => {
    write("curated.json", ["alpha"]);
    run();
    expect(run(["--check"]).code).toBe(0);
    write("curated.json", ["alpha", "beta"]);
    const stale = run(["--check"]);
    expect(stale.code).toBe(1);
    expect(stale.output).toMatch(/Out of date: .*brandData\.ts/);
  });

  it("refuses a notices file that has no markers instead of appending", () => {
    write("curated.json", ["alpha"]);
    write("NOTICES.md", "# Notices\n");
    expect(run().output).toMatch(/needs the markers/);
  });
});

describe("the brands that ship", () => {
  it("are what the pinned simple-icons builds today: module and notices are up to date", () => {
    const output = execFileSync("node", [SCRIPT, "--check"], { encoding: "utf8" });
    expect(output).toMatch(/up to date \(11 brands, simple-icons 16\.36\.0\)/);
  });

  it("pin simple-icons to one exact version, as a dev dependency of the kit only", () => {
    const manifest = JSON.parse(readFileSync(join(ROOT, "package.json"), "utf8"));
    expect(manifest.devDependencies["simple-icons"]).toBe("16.36.0");
    expect(manifest.dependencies?.["simple-icons"]).toBeUndefined();
    const site = JSON.parse(readFileSync(join(ROOT, "template", "package.json"), "utf8"));
    expect(JSON.stringify(site)).not.toMatch(/simple-icons/);
  });

  it("have no icon with another licence on the default allowlist", () => {
    const allowlist = JSON.parse(
      readFileSync(join(ROOT, "scripts", "brands", "allowlist.json"), "utf8"),
    );
    expect(allowlist).toEqual({});
  });
});
